def evaluate(current_reputation, observation, my_history, round_num):
    # Use exponential decay for reputation - recent actions weigh more
    decay_factor = 0.85 if round_num > 1 else 1.0
    reputation_decay = current_reputation * decay_factor

    if observation["action"] == "cooperate":
        # Stronger reward for cooperation, especially in early rounds
        if round_num <= 5:
            new_reputation = reputation_decay + 1.5
        else:
            new_reputation = reputation_decay + 1.0
    else:
        # Heavier penalty for defection
        new_reputation = reputation_decay - 1.5

    return new_reputation

def decide(recipient_reputation, round_num, my_history):
    # Check my recent history (last 3 actions)
    recent_coops = sum(1 for action in my_history[-3:] if action == "cooperate") if len(my_history) >= 3 else len([a for a in my_history if a == "cooperate"])

    # Dynamic threshold based on round number and my own cooperation history
    if round_num <= 5:
        # Early game: be more cooperative to build reputation
        cooperate_threshold = -0.5
    elif round_num <= 20:
        # Mid game: moderate threshold
        cooperate_threshold = 0.0
    else:
        # Late game: more selective
        cooperate_threshold = 0.5

    # Also consider my own recent cooperation rate
    my_recent_rate = recent_coops / max(3, len(my_history[-3:])) if my_history else 0.5

    # Adjust threshold based on my own recent behavior
    if my_recent_rate < 0.5:
        cooperate_threshold -= 0.2  # Be more forgiving if I've been defecting

    return recipient_reputation >= cooperate_threshold

